import{_ as i,a0 as l,w as c,s,ao as p,I as r,x as o,a1 as t,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"Nmcli 網絡管理命令列工具基礎 | LCTT x X-CMD","titleTemplate":false,"description":"Nmcli 網絡管理命令列工具基礎 | LCTT (201509) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Nmcli 網絡管理命令列工具基礎 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Nmcli 網絡管理命令列工具基礎 | LCTT (201509) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201509/20150824 Basics Of NetworkManager Command Line Tool Nmcli","title":"Nmcli 網絡管理命令列工具基礎","tag":"201509","desc":""},"relativePath":"201509/20150824 Basics Of NetworkManager Command Line Tool Nmcli.md","filePath":"[post].md"}'),d={name:"201509/20150824 Basics Of NetworkManager Command Line Tool Nmcli.md"};function m(h,e,f,g,u,w){const n=l("Link");return c(),s("div",null,[e[11]||(e[11]=p(`<h1 id="nmcli-網絡管理命令列工具基礎" tabindex="-1">Nmcli 網絡管理命令列工具基礎 <a class="header-anchor" href="#nmcli-網絡管理命令列工具基礎" aria-label="Permalink to “Nmcli 網絡管理命令列工具基礎”">​</a></h1><p><img src="http://1102047360.rsc.cdn77.org/wp-content/uploads/2015/08/networking1.jpg" alt=""></p><h3 id="介紹" tabindex="-1">介紹 <a class="header-anchor" href="#介紹" aria-label="Permalink to “介紹”">​</a></h3><p>在本教程中，我們會在CentOS / RHEL 7中討論網絡管理工具（NetworkManager command line tool），也叫<strong>nmcli</strong>。那些使用<strong>ifconfig</strong>的用户應該在CentOS 7中避免使用<strong>ifconfig</strong> 了。</p><p>讓我們用nmcli工具配置一些網絡設置。</p><h4 id="要得到系統中所有接口的地址信息" tabindex="-1">要得到系統中所有接口的地址信息 <a class="header-anchor" href="#要得到系統中所有接口的地址信息" aria-label="Permalink to “要得到系統中所有接口的地址信息”">​</a></h4><pre><code>[root@localhost ~]# ip addr show
</code></pre><p><strong>示例輸出：</strong></p><pre><code>1: lo: &lt;LOOPBACK,UP,LOWER_UP&gt; mtu 65536 qdisc noqueue state UNKNOWN 
 link/loopback 00:00:00:00:00:00 brd 00:00:00:00:00:00
 inet 127.0.0.1/8 scope host lo
 valid_lft forever preferred_lft forever
 inet6 ::1/128 scope host 
 valid_lft forever preferred_lft forever
2: eno16777736: &lt;BROADCAST,MULTICAST,UP,LOWER_UP&gt; mtu 1500 qdisc pfifo_fast state UP qlen 1000
 link/ether 00:0c:29:67:2f:4c brd ff:ff:ff:ff:ff:ff
 inet 192.168.1.51/24 brd 192.168.1.255 scope global eno16777736
 valid_lft forever preferred_lft forever
 inet6 fe80::20c:29ff:fe67:2f4c/64 scope link 
 valid_lft forever preferred_lft forever
</code></pre><h4 id="檢索與已連接的接口相關的數據包統計" tabindex="-1">檢索與已連接的接口相關的數據包統計 <a class="header-anchor" href="#檢索與已連接的接口相關的數據包統計" aria-label="Permalink to “檢索與已連接的接口相關的數據包統計”">​</a></h4><pre><code>[root@localhost ~]# ip -s link show eno16777736
</code></pre><p><strong>示例輸出：</strong></p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/08/unxmen_0111.png" alt=""></p><h4 id="得到路由配置" tabindex="-1">得到路由配置 <a class="header-anchor" href="#得到路由配置" aria-label="Permalink to “得到路由配置”">​</a></h4><pre><code>[root@localhost ~]# ip route
</code></pre><p>示例輸出：</p><pre><code>default via 192.168.1.1 dev eno16777736 proto static metric 100 
192.168.1.0/24 dev eno16777736 proto kernel scope link src 192.168.1.51 metric 100
</code></pre><h4 id="分析主機-網站路徑" tabindex="-1">分析主機/網站路徑 <a class="header-anchor" href="#分析主機-網站路徑" aria-label="Permalink to “分析主機/網站路徑”">​</a></h4><pre><code>[root@localhost ~]# tracepath unixmen.com
</code></pre><p>輸出像traceroute，但是更加完整。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/08/unxmen_01211.png" alt=""></p><h3 id="nmcli-工具" tabindex="-1">nmcli 工具 <a class="header-anchor" href="#nmcli-工具" aria-label="Permalink to “nmcli 工具”">​</a></h3><p><strong>nmcli</strong> 是一個非常豐富和靈活的命令列工具。nmcli使用的情況有：</p><ul><li><strong>設備</strong> – 正在使用的網絡接口</li><li><strong>連接</strong> – 一組配置設置，對於一個單一的設備可以有多個連接，可以在連接之間切換。</li></ul><h4 id="找出有多少連接服務於多少設備" tabindex="-1">找出有多少連接服務於多少設備 <a class="header-anchor" href="#找出有多少連接服務於多少設備" aria-label="Permalink to “找出有多少連接服務於多少設備”">​</a></h4><pre><code>[root@localhost ~]# nmcli connection show
</code></pre><p><img src="http://www.unixmen.com/wp-content/uploads/2015/08/unxmen_013.png" alt=""></p><h4 id="得到特定連接的詳情" tabindex="-1">得到特定連接的詳情 <a class="header-anchor" href="#得到特定連接的詳情" aria-label="Permalink to “得到特定連接的詳情”">​</a></h4><pre><code>[root@localhost ~]# nmcli connection show eno1
</code></pre><p><strong>示例輸出：</strong></p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/08/unxmen_0141.png" alt=""></p><h4 id="得到網絡設備狀態" tabindex="-1">得到網絡設備狀態 <a class="header-anchor" href="#得到網絡設備狀態" aria-label="Permalink to “得到網絡設備狀態”">​</a></h4><pre><code>[root@localhost ~]# nmcli device status
</code></pre><hr><pre><code> DEVICE               TYPE              STATE          CONNECTION 
eno16777736            ethernet      connected              eno1 
lo                     loopback      unmanaged               --
</code></pre><h4 id="使用-dhcp-創建新的連接" tabindex="-1">使用“dhcp”創建新的連接 <a class="header-anchor" href="#使用-dhcp-創建新的連接" aria-label="Permalink to “使用“dhcp”創建新的連接”">​</a></h4><pre><code>[root@localhost ~]# nmcli connection add con-name &quot;dhcp&quot; type ethernet ifname eno16777736
</code></pre><p>這裏，</p><ul><li><strong>connection add</strong> – 添加新的連接</li><li><strong>con-name</strong> – 連接名</li><li><strong>type</strong> – 設備類型</li><li><strong>ifname</strong> – 接口名</li></ul><p>這個命令會使用dhcp協議添加連接</p><p><strong>示例輸出：</strong></p><pre><code>Connection &#39;dhcp&#39; (163a6822-cd50-4d23-bb42-8b774aeab9cb) successfully added.
</code></pre><h4 id="不通過dhcp分配ip-使用-static-添加地址" tabindex="-1">不通過dhcp分配IP，使用“static”添加地址 <a class="header-anchor" href="#不通過dhcp分配ip-使用-static-添加地址" aria-label="Permalink to “不通過dhcp分配IP，使用“static”添加地址”">​</a></h4><pre><code>[root@localhost ~]# nmcli connection add con-name &quot;static&quot; ifname eno16777736 autoconnect no type ethernet ip4 192.168.1.240 gw4 192.168.1.1
</code></pre><p><strong>示例輸出：</strong></p><pre><code>Connection &#39;static&#39; (8e69d847-03d7-47c7-8623-bb112f5cc842) successfully added.
</code></pre><p><strong>更新連接：</strong></p><pre><code>[root@localhost ~]# nmcli connection up eno1
</code></pre><p>再檢查一遍，ip地址是否已經改變</p><pre><code>[root@localhost ~]# ip addr show
</code></pre><p><img src="http://www.unixmen.com/wp-content/uploads/2015/08/unxmen_0151.png" alt=""></p><h4 id="添加dns設置到靜態連接中" tabindex="-1">添加DNS設置到靜態連接中 <a class="header-anchor" href="#添加dns設置到靜態連接中" aria-label="Permalink to “添加DNS設置到靜態連接中”">​</a></h4><pre><code>[root@localhost ~]# nmcli connection modify &quot;static&quot; ipv4.dns 202.131.124.4
</code></pre><h4 id="添加更多的dns" tabindex="-1">添加更多的DNS <a class="header-anchor" href="#添加更多的dns" aria-label="Permalink to “添加更多的DNS”">​</a></h4><pre><code>[root@localhost ~]# nmcli connection modify &quot;static&quot; +ipv4.dns 8.8.8.8
</code></pre><p><strong>注意</strong>：要使用額外的<strong>+</strong>符號，並且要是<strong>+ipv4.dns</strong>，而不是<strong>ip4.dns</strong>。</p><p>####添加一個額外的ip地址####</p><pre><code>[root@localhost ~]# nmcli connection modify &quot;static&quot; +ipv4.addresses 192.168.200.1/24
</code></pre><p>使用命令刷新設置：</p><pre><code>[root@localhost ~]# nmcli connection up eno1
</code></pre><p><img src="http://www.unixmen.com/wp-content/uploads/2015/08/unxmen_016.png" alt=""></p><p>你會看見，設置生效了。</p><p>完結。</p><hr>`,64)),r("p",null,[e[1]||(e[1]=o("via: ",-1)),t(n,{href:"http://www.unixmen.com/basics-networkmanager-command-line-tool-nmcli/"},{default:a(()=>[...e[0]||(e[0]=[o("http://www.unixmen.com/basics-networkmanager-command-line-tool-nmcli/",-1)])]),_:1})]),r("p",null,[e[4]||(e[4]=o("作者：Rajneesh Upadhyay 譯者：",-1)),t(n,{href:"https://github.com/geekpi"},{default:a(()=>[...e[2]||(e[2]=[o("geekpi",-1)])]),_:1}),e[5]||(e[5]=o(" 校對：",-1)),t(n,{href:"https://github.com/wxy"},{default:a(()=>[...e[3]||(e[3]=[o("wxy",-1)])]),_:1})]),r("p",null,[e[8]||(e[8]=o("本文由 ",-1)),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[6]||(e[6]=[o("LCTT",-1)])]),_:1}),e[9]||(e[9]=o(" 原創翻譯，",-1)),t(n,{href:"https://linux.cn/"},{default:a(()=>[...e[7]||(e[7]=[o("Linux中國",-1)])]),_:1}),e[10]||(e[10]=o(" 榮譽推出",-1))])])}const T=i(d,[["render",m]]);export{k as __pageData,T as default};
